/* إصلاح شامل لمشاكل ظهور بطاقات الأدوات والتفكير (Thought, Tool calls) التي تظهر كخطوط */
.thought-container, .tool-call, [class*="thought"], [class*="tool"], .agent-thought, .execution-step, div[style*="height: 0"], .css-175oi1r {
  min-height: 50px !important;
  max-height: none !important;
  height: auto !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  overflow: visible !important;
  background: rgba(255, 255, 255, 0.05) !important;
  border: 1px solid rgba(255, 255, 255, 0.15) !important;
  border-radius: 8px !important;
  padding: 12px !important;
  margin: 8px 0 !important;
  color: #ffffff !important;
}

/* ضمان ظهور أيقونات الأدوات والنصوص بداخله */
.thought-container *, .tool-call *, [class*="thought"] *, [class*="tool"] * {
  visibility: visible !important;
  opacity: 1 !important;
  color: inherit !important;
  display: inline-block;
}

/* إزالة الخطوط الوهمية أو العناصر المخفية ذات الارتفاع الصفري */
hr + div:empty, div:not([class]):not([id]) > hr {
  display: none !important;
}
